BEGIN;
ALTER TABLE family.families ADD COLUMN basic_data jsonb NOT NULL DEFAULT '{}';
ALTER TABLE family.family_memberships ADD COLUMN profile_data jsonb NOT NULL DEFAULT '{}';
-- A domain review is partial; legacy full-score snapshots and their constraints remain intact.
CREATE TABLE assessment.domain_reviews(
 id uuid PRIMARY KEY DEFAULT gen_random_uuid(),family_id uuid NOT NULL REFERENCES family.families(id),
 domain_code text NOT NULL CHECK(domain_code='LIVELIHOOD'),model_id uuid NOT NULL REFERENCES assessment.models(id),
 state text NOT NULL DEFAULT 'DRAFT' CHECK(state IN ('DRAFT','READY','SUBMITTED','IN_REVIEW','RETURNED','APPROVED')),
 version integer NOT NULL DEFAULT 1,payload jsonb NOT NULL DEFAULT '{}',created_by uuid NOT NULL REFERENCES identity.accounts(id),
 created_at timestamptz NOT NULL DEFAULT now(),updated_at timestamptz NOT NULL DEFAULT now()
);
CREATE UNIQUE INDEX one_open_domain_review ON assessment.domain_reviews(family_id,domain_code) WHERE state<>'APPROVED';
CREATE TABLE assessment.domain_submissions(
 id uuid PRIMARY KEY DEFAULT gen_random_uuid(),review_id uuid NOT NULL REFERENCES assessment.domain_reviews(id),
 revision integer NOT NULL,snapshot jsonb NOT NULL,submitted_by uuid NOT NULL REFERENCES identity.accounts(id),
 submitted_at timestamptz NOT NULL DEFAULT now(),UNIQUE(review_id,revision)
);
CREATE TABLE assessment.domain_decisions(
 id uuid PRIMARY KEY DEFAULT gen_random_uuid(),submission_id uuid NOT NULL UNIQUE REFERENCES assessment.domain_submissions(id),
 decision text NOT NULL CHECK(decision IN ('APPROVED','RETURNED')),reason text,decided_by uuid NOT NULL REFERENCES identity.accounts(id),
 decided_at timestamptz NOT NULL DEFAULT now(),valid_until timestamptz,
 CHECK((decision='RETURNED' AND length(trim(reason))>0 AND valid_until IS NULL) OR (decision='APPROVED' AND valid_until IS NOT NULL))
);
CREATE TRIGGER domain_submission_immutable BEFORE UPDATE OR DELETE ON assessment.domain_submissions FOR EACH ROW EXECUTE FUNCTION guidance.immutable();
CREATE TRIGGER domain_decision_immutable BEFORE UPDATE OR DELETE ON assessment.domain_decisions FOR EACH ROW EXECUTE FUNCTION guidance.immutable();
CREATE TRIGGER domain_review_no_delete BEFORE DELETE ON assessment.domain_reviews FOR EACH ROW EXECUTE FUNCTION guidance.no_delete();
CREATE FUNCTION assessment.domain_review_guard() RETURNS trigger LANGUAGE plpgsql AS $$ BEGIN
 IF OLD.state='APPROVED' THEN RAISE EXCEPTION 'Approved domain review is immutable'; END IF;
 IF OLD.state IN ('SUBMITTED','IN_REVIEW') AND NEW.payload IS DISTINCT FROM OLD.payload THEN RAISE EXCEPTION 'Submitted answers are immutable'; END IF;
 IF NOT (NEW.state=OLD.state OR (OLD.state IN ('DRAFT','READY','RETURNED') AND NEW.state IN ('DRAFT','READY','SUBMITTED')) OR (OLD.state='SUBMITTED' AND NEW.state IN ('IN_REVIEW','APPROVED','RETURNED')) OR (OLD.state='IN_REVIEW' AND NEW.state IN ('APPROVED','RETURNED'))) THEN RAISE EXCEPTION 'Invalid review transition'; END IF;
 RETURN NEW; END $$;
CREATE TRIGGER domain_review_guard BEFORE UPDATE ON assessment.domain_reviews FOR EACH ROW EXECUTE FUNCTION assessment.domain_review_guard();
INSERT INTO assessment.models(version,title,state,definition,form_schema) VALUES('1.00-LIVELIHOOD','معیشت و اقتصاد — راهنمای ۱٫۰۰ (ارزیابی جزئی)','APPROVED','{"scope": "LIVELIHOOD", "max": 30, "indicators": [{"key": "adequacy", "label": "کفایت درآمد برای نیازهای پایه", "max": 15, "options": [{"code": "0", "label": "کافی", "points": 0}, {"code": "1", "label": "نزدیک به کافی", "points": 5}, {"code": "2", "label": "ناکافی", "points": 10}, {"code": "3", "label": "بسیار ناکافی", "points": 15}]}, {"key": "stability", "label": "ثبات درآمد", "max": 6, "options": [{"code": "0", "label": "ثابت", "points": 0}, {"code": "1", "label": "نوسانی", "points": 2}, {"code": "2", "label": "موقت", "points": 4}, {"code": "3", "label": "بی‌درآمد", "points": 6}]}, {"key": "pressure", "label": "فشار هزینه‌های ضروری", "max": 5, "options": [{"code": "0", "label": "کم", "points": 0}, {"code": "1", "label": "متوسط", "points": 1}, {"code": "2", "label": "زیاد", "points": 3}, {"code": "3", "label": "بسیار زیاد", "points": 5}]}, {"key": "debt", "label": "بدهی و تعهدات مؤثر", "max": 4, "options": [{"code": "0", "label": "کم یا فاقد اثر", "points": 0}, {"code": "1", "label": "متوسط", "points": 1}, {"code": "2", "label": "زیاد", "points": 2}, {"code": "3", "label": "بحرانی", "points": 4}]}]}'::jsonb,'{"checks": ["اطلاعات پایه خانواده کامل است", "اعضای خانواده و اطلاعات هویتی ثبت شده‌اند", "مدارک هویتی الزامی ثبت شده‌اند", "حوزه معیشت کامل است؛ چهار حوزه دیگر هنوز ارزیابی نشده‌اند", "مورد الزامی نامشخص یا ثبت‌نشده باقی نمانده است", "شواهد موضوعی لازم ثبت شده‌اند", "یک اثر دوبار امتیاز نگرفته است", "فوریت موضوع‌ها بررسی شده است", "نشانه بحرانی بررسی شده و در صورت وجود اقدام فوری آغاز شده است", "جمع‌بندی با شواهد سازگار است"], "documentKinds": {"NATIONAL_CARD": "تصویر کارت ملی سرپرست", "FAMILY_BOOK": "صفحات شناسنامه دارای مشخصات خانواده", "INCOME": "درآمد / مستمری / حمایت مستمر", "DEBT": "اقساط و بدهی", "EXPENSE": "هزینه ضروری", "OTHER": "سایر"}, "schema": {"income": [{"key": "type", "label": "منبع تأمین معاش", "options": ["بدون درآمد", "کار روزمزدی/موردی", "کار فصلی", "خوداشتغالی محدود", "حقوق", "مستمری", "کمک بستگان", "کمک نهادها/کانون", "درآمد اعضای خانواده", "قرض برای گذران زندگی", "سایر"]}, {"key": "recipient", "label": "دریافت‌کننده / توضیح نبود درآمد"}, {"key": "amount", "label": "مبلغ تقریبی (تومان)", "type": "number"}, {"key": "period", "label": "دوره دریافت", "options": ["بدون دریافت", "روزانه", "هفتگی", "ماهانه", "فصلی", "موردی", "نامنظم"]}, {"key": "continuity", "label": "استمرار", "options": ["فاقد منبع", "پایدار", "نسبتاً پایدار", "ناپایدار", "موقت"]}, {"key": "startedOn", "label": "تاریخ شروع در صورت معلوم بودن", "type": "date", "optional": true}, {"key": "notes", "label": "توضیح", "optional": true}], "employment": [{"key": "memberId", "label": "عضو خانواده", "type": "member"}, {"key": "state", "label": "وضعیت تأمین معاش", "options": ["بدون شغل و درآمد", "بیکار با درآمد محدود از منابع دیگر", "کار روزمزدی/موردی", "کار فصلی", "خوداشتغالی محدود", "شغل نسبتاً پایدار", "مستمری", "کودک / خارج از سن کار", "سایر"]}, {"key": "skill", "label": "مهارت/حرفه (در صورت وجود)", "optional": true}, {"key": "ability", "label": "توان کار", "options": ["دارد", "ندارد"]}, {"key": "barrier", "label": "مانع اشتغال (یا ندارد)"}, {"key": "notes", "label": "توضیح", "optional": true}], "expenses": [{"key": "type", "label": "نوع هزینه/تعهد", "options": ["خوراک و نیازهای روزمره", "مسکن/اجاره", "آب، برق، گاز و خدمات ضروری", "درمان و دارو", "آموزش", "رفت‌وآمد ضروری", "اقساط و بدهی‌ها", "سایر"]}, {"key": "amount", "label": "مبلغ تقریبی (تومان)", "type": "number"}, {"key": "payment", "label": "وضعیت پرداخت", "options": ["پرداخت‌شده", "بخشی پرداخت‌شده", "پرداخت‌نشده", "معوق", "هزینه‌ای ندارد"]}, {"key": "effect", "label": "اثر بر خانواده"}, {"key": "evidence", "label": "شاهد / توضیح"}], "evidence": [{"key": "source", "label": "منبع اطلاعات", "options": ["گفت‌وگوی مستقیم با خانواده", "مشاهده سرگروه", "بازدید", "سوابق کانون", "منبع قابل اتکا", "مدرک رسمی", "سایر"]}, {"key": "description", "label": "شرح شاهد و موضوع مرتبط"}]}, "criticalOptions": ["عدم دسترسی به خوراک یا نیاز حیاتی اولیه", "بحران فعال مختل‌کننده نیازهای حیاتی خانواده"]}'::jsonb);
COMMIT;
